<script setup lang="ts">
import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import QRCode from 'qrcode';import {useCoffee} from '../stores/coffee';import type {Table} from '../../../../packages/shared/src/types';import {stateLabels,money} from '../../../../packages/shared/src/domain';import Modal from '../../../../packages/ui/src/Modal.vue';import Icon from '../components/Icon.vue';
const s=useCoffee();const router=useRouter();const area=ref('all');const filter=ref('all');const selected=ref<Table>();const dialog=ref('');const target=ref('');const qr=ref('');const form=ref({name:'',area:'Tầng 1',seats:2});const areas=computed(()=>[...new Set(s.tables.map(t=>t.area))]);const tables=computed(()=>s.tables.filter(t=>(area.value==='all'||t.area===area.value)&&(filter.value==='all'||t.state===filter.value)));
const tableOrders=computed(()=>selected.value?s.orders.filter(o=>o.tableId===selected.value!.id&&!['cancelled','completed'].includes(o.state)):[]);
function open(t:Table){selected.value=t;dialog.value='detail'}
async function showQr(){if(!selected.value)return;qr.value=await QRCode.toDataURL(location.origin+'/order/'+selected.value.token,{width:320,margin:3});dialog.value='qr'}
function create(){const result=s.upsert('tables',{id:crypto.randomUUID(),branchId:s.branchId,...form.value,state:'available',active:true,token:crypto.randomUUID().replaceAll('-','')});if(result)dialog.value=''}
function move(merge=false){if(selected.value&&s.run(()=>s.repo.moveTable(selected.value!.id,target.value,merge)))dialog.value=''}
function addOrder(){if(!selected.value)return;s.tableId=selected.value.id;router.push('/pos')}
</script>
<template><div class="page"><div class="page-heading"><div><h2>Bàn & khu vực</h2><p>Theo dõi không gian và phiên phục vụ tại {{s.branch.name}}.</p></div><button v-if="s.canManage" class="btn primary" @click="dialog='create';form={name:'',area:'Tầng 1',seats:2}"><Icon name="plus"/>Thêm bàn</button></div><div class="table-stats"><button v-for="state in ['all','available','occupied','ordering','waiting_payment','cleaning']" :key="state" :class="{selected:filter===state}" @click="filter=state"><i :class="state"></i><span>{{state==='all'?'Tất cả':stateLabels[state]}}</span><b>{{s.tables.filter(t=>state==='all'||t.state===state).length}}</b></button></div><div class="category-tabs"><button @click="area='all'" :class="{selected:area==='all'}">Tất cả khu vực</button><button v-for="a in areas" :key="a" @click="area=a" :class="{selected:area===a}">{{a}}</button></div><div class="tables-grid"><button v-for="t in tables" :key="t.id" class="table-card" :class="t.state" @click="open(t)"><div class="table-card-top"><span>{{t.area}}</span><span>{{t.seats}} chỗ</span></div><Icon name="table" :size="48"/><strong>{{t.name}}</strong><span class="status" :class="t.state">{{stateLabels[t.state]}}</span><small v-if="s.orders.some(o=>o.tableId===t.id&&!['completed','cancelled'].includes(o.state))">{{money(s.orders.filter(o=>o.tableId===t.id&&!['completed','cancelled'].includes(o.state)).reduce((n,o)=>n+Math.max(0,o.total-o.paid),0))}} chưa thu</small></button></div><section v-if="s.state.calls.some(c=>!c.done&&s.tables.some(t=>t.id===c.tableId))" class="panel calls-panel"><h3>Yêu cầu từ khách</h3><div v-for="c in s.state.calls.filter(c=>!c.done&&s.tables.some(t=>t.id===c.tableId))" :key="c.id" class="list-row"><span>{{s.tables.find(t=>t.id===c.tableId)?.name}} · {{c.kind}}</span><button class="btn small" @click="s.run(()=>s.repo.resolveCall(c.id))">Đã xử lý</button></div></section></div>
<Modal v-if="dialog==='detail'&&selected" :title="selected.name" @close="dialog=''"><div class="table-detail-status"><span class="status" :class="selected.state">{{stateLabels[selected.state]}}</span><span>{{selected.area}} · {{selected.seats}} chỗ</span></div><div v-for="o in tableOrders" :key="o.id" class="list-row"><span>{{o.number}}<small>{{stateLabels[o.state]}}</small></span><b>{{money(o.total-o.paid)}}</b></div><div class="button-grid"><button class="btn primary" @click="addOrder"><Icon name="plus"/>Gọi món</button><button class="btn outline" @click="showQr"><Icon name="mobile"/>QR của bàn</button><button class="btn outline" @click="dialog='move';target=''">Chuyển bàn</button><button class="btn outline" @click="dialog='merge';target=''">Gộp bàn</button><button class="btn outline" @click="s.run(()=>s.repo.setTable(selected!.id,'occupied'));dialog=''">Mở phiên bàn</button><button class="btn outline" @click="s.run(()=>s.repo.setTable(selected!.id,selected!.state==='cleaning'?'available':'cleaning'));dialog=''">{{selected.state==='cleaning'?'Đã dọn xong':'Đóng phiên & dọn'}}</button><button v-if="s.canManage" class="btn danger" @click="s.archive('tables',selected!.id);dialog=''">Ngừng sử dụng bàn</button></div></Modal>
<Modal v-if="(dialog==='move'||dialog==='merge')&&selected" :title="(dialog==='move'?'Chuyển ':'Gộp ')+selected.name" @close="dialog=''"><label class="field"><span>Bàn đích</span><select v-model="target"><option value="">Chọn bàn</option><option v-for="t in s.tables.filter(t=>t.id!==selected!.id&&(dialog==='merge'||t.state==='available'))" :value="t.id" :key="t.id">{{t.name}} · {{stateLabels[t.state]}}</option></select></label><p class="muted">Đơn và lịch sử được giữ nguyên khi chuyển hoặc gộp.</p><button class="btn primary full" :disabled="!target" @click="move(dialog==='merge')">Xác nhận {{dialog==='move'?'chuyển':'gộp'}} bàn</button></Modal>
<Modal v-if="dialog==='qr'&&selected" :title="'QR · '+selected.name" @close="dialog=''"><div class="qr-table"><img :src="qr" class="qr-image" alt="QR gọi món tại bàn"><p>{{s.branch.name}} · {{selected.name}}</p><RouterLink class="btn primary" :to="'/order/'+selected.token">Mở menu khách</RouterLink><a class="btn outline" :href="qr" :download="selected.name+'-QR.png'">Tải QR</a><p class="muted small-copy">Link QR dùng để xem menu. Thay đổi và đơn trên từng trình duyệt chưa đồng bộ.</p><button v-if="s.canManage" class="text-link" @click="s.run(()=>s.repo.rotateTable(selected!.id));dialog=''">Thay mã QR của bàn</button></div></Modal>
<Modal v-if="dialog==='create'" title="Thêm bàn" @close="dialog=''"><form @submit.prevent="create"><label class="field"><span>Tên bàn</span><input v-model="form.name" required maxlength="50"></label><label class="field"><span>Khu vực / tầng</span><input v-model="form.area" required maxlength="50" list="areas"><datalist id="areas"><option v-for="a in areas" :key="a">{{a}}</option></datalist></label><label class="field"><span>Số chỗ</span><input type="number" min="1" max="20" v-model.number="form.seats" required></label><button class="btn primary full">Lưu bàn</button></form></Modal></template>
